<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('admin'); $user = current_user();
$counts = db()->query("SELECT COUNT(*) AS total, SUM(status = 'pending') AS pending, SUM(status = 'approved') AS approved, SUM(status = 'rejected') AS rejected FROM leave_applications")->fetch();
$employees = (int) db()->query("SELECT COUNT(*) FROM users WHERE role = 'employee' AND is_active = 1")->fetchColumn();
$recent = db()->query("SELECT la.*, u.full_name, u.department, lt.name AS leave_type FROM leave_applications la JOIN users u ON u.id = la.user_id JOIN leave_types lt ON lt.id = la.leave_type_id ORDER BY la.created_at DESC LIMIT 5");
$pageTitle = 'HR overview'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="dashboard-intro"><div><span class="eyebrow">People operations / Control centre</span><h2>Welcome, <?= e(explode(' ', $user['full_name'])[0]) ?>.</h2><p class="muted mb-0">A quick read on leave activity across Northstar.</p></div><a class="btn btn-primary" href="<?= e(base_url('admin/leaves.php')) ?>">Review requests <span>&rarr;</span></a></div><div class="stats-grid"><div class="stat-card tone-gold"><div class="stat-label">Needs review</div><div class="stat-value"><?= (int) $counts['pending'] ?></div><div class="stat-meta">Pending applications</div></div><div class="stat-card tone-mint"><div class="stat-label">Employees</div><div class="stat-value"><?= $employees ?></div><div class="stat-meta">Active team members</div></div><div class="stat-card tone-peach"><div class="stat-label">Approved</div><div class="stat-value"><?= (int) $counts['approved'] ?></div><div class="stat-meta">All time requests</div></div><div class="stat-card"><div class="stat-label">Total requests</div><div class="stat-value"><?= (int) $counts['total'] ?></div><div class="stat-meta"><a class="text-link" href="<?= e(base_url('admin/reports.php')) ?>">View reports &rarr;</a></div></div></div><section class="panel"><div class="panel-heading"><h3>Latest leave activity</h3><a class="text-link" href="<?= e(base_url('admin/leaves.php')) ?>">View all &rarr;</a></div><table class="table"><thead><tr><th>Employee</th><th>Leave type</th><th>Dates</th><th>Days</th><th>Status</th></tr></thead><tbody><?php while ($item = $recent->fetch()): ?><tr><td><strong><?= e($item['full_name']) ?></strong><br><small class="muted"><?= e($item['department']) ?></small></td><td><?= e($item['leave_type']) ?></td><td><?= e(date('M j', strtotime($item['start_date']))) ?> - <?= e(date('M j, Y', strtotime($item['end_date']))) ?></td><td><?= e((string) $item['days']) ?></td><td><span class="status status-<?= e($item['status']) ?>"><?= e($item['status']) ?></span></td></tr><?php endwhile; ?></tbody></table></section></div><?php require __DIR__ . '/../includes/footer.php'; ?>
